112		public ShoppingCart delete(@PathParam("cartId") String cartId,
113								   @PathParam("itemId") String itemId,
114								   @PathParam("quantity") int quantity) {
115	
116			List<ShoppingCartItem> toRemoveList = new ArrayList<>();
117	
118			ShoppingCart cart = shoppingCartService.getShoppingCart(cartId);
119	
120			cart.getShoppingCartItemList().stream()
121					.filter(sci -> sci.getProduct().getItemId().equals(itemId))
122					.forEach(sci -> {
123						if (quantity >= sci.getQuantity()) {
124							toRemoveList.add(sci);
125						} else {
126							sci.setQuantity(sci.getQuantity() - quantity);
127						}
128					});
129	
130			toRemoveList.forEach(cart::removeShoppingCartItem);
131	
132			shoppingCartService.priceShoppingCart(cart);
133			return cart;
134		}
