138		private List<ShoppingCartItem> dedupeCartItems(List<ShoppingCartItem> cartItems) {
139			List<ShoppingCartItem> result = new ArrayList<>();
140			Map<String, Integer> quantityMap = new HashMap<>();
141			for (ShoppingCartItem sci : cartItems) {
142				if (quantityMap.containsKey(sci.getProduct().getItemId())) {
143					quantityMap.put(sci.getProduct().getItemId(), quantityMap.get(sci.getProduct().getItemId()) + sci.getQuantity());
144				} else {
145					quantityMap.put(sci.getProduct().getItemId(), sci.getQuantity());
146				}
147			}
148	
149			for (String itemId : quantityMap.keySet()) {
150				Product p = shoppingCartService.getProduct(itemId);
151				ShoppingCartItem newItem = new ShoppingCartItem();
152				newItem.setQuantity(quantityMap.get(itemId));
153				newItem.setPrice(p.getPrice());
154				newItem.setProduct(p);
155				result.add(newItem);
156			}
157			return result;
158		}
159	}
